#include <iostream>
#include <cstring>
using namespace std;

const int MAXT = 20005;
int table[MAXT];

bool isPrime(int x) {
    if (x < 2) return false;
    for (int i = 2; (long long)i * i <= x; i++)
        if (x % i == 0) return false;
    return true;
}

int main() {
    int msize, n;
    if (!(cin >> msize >> n)) return 0;

    int tsize = msize;
    while (!isPrime(tsize)) tsize++;
    if (tsize < 2) tsize = 2;

    memset(table, -1, sizeof(table));

    for (int i = 0; i < n; i++) {
        int key;
        cin >> key;
        int pos = -1;
        for (int step = 0; step < tsize; step++) {
            int p = (key + step * step) % tsize;
            if (table[p] == -1) {
                table[p] = key;
                pos = p;
                break;
            }
        }
        if (i) cout << ' ';
        if (pos >= 0) cout << pos;
        else cout << '-';
    }
    cout << "\n";
    return 0;
}
